    pub struct ThreadLLSimple {
        pub instance: Ghost<Mim::Instance>,
        pub heap_id: Ghost<HeapId>,

        pub atomic: AtomicPtr<Node, _, Tracked<LL>, _>,
    }

    pub closed spec fn wf(&self) -> bool {
